SELECT paid_month, pct_success, failed_count FROM (SELECT DATE_FORMAT(paid_at, 'yyyy-MM') AS paid_month, ROUND((100 * SUM(CASE WHEN status = 'SUCCESS' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_success, SUM(CASE WHEN status = 'FAILED' THEN 1 ELSE 0 END) AS failed_count FROM payments GROUP BY DATE_FORMAT(paid_at, 'yyyy-MM')) AS sub WHERE failed_count >= 38 ORDER BY failed_count, paid_month LIMIT 1
